// ===== CONFIG =====
const STRIPE_KEY='rk_live_your_restricted_readonly_key';
const OPENAI_KEY='sk-your-openai-key';
const TZ='America/Chicago';
// ==================

const now=new Date();
const startY=Math.floor((now.getTime()-24*3600*1000)/1000);
const startToday=Math.floor(now.getTime()/1000)-86400;

async function stripe(path){try{const r=await this.helpers.httpRequest({method:'GET',url:'https://api.stripe.com/v1/'+path,headers:{'Authorization':'Bearer '+STRIPE_KEY}});return r;}catch(e){return{data:[],_error:String(e.message||e)};}}

const charges=await stripe.call(this,'charges?limit=100&created[gte]='+startY);
let gross=0,count=0,refunds=0;
(charges.data||[]).forEach(function(c){if(c.paid&&c.status==='succeeded'){gross+=c.amount;count++;refunds+=c.amount_refunded||0;}});
const net=(gross-refunds)/100;
const customers=await stripe.call(this,'customers?limit=100&created[gte]='+startY);
const newCust=(customers.data||[]).length;

const facts='Yesterday: $'+net.toFixed(2)+' net revenue across '+count+' payment(s), '+newCust+' new customer(s).'+(charges._error?(' [stripe error: '+charges._error+']'):'');

let summary=facts;
try{const r=await this.helpers.httpRequest({method:'POST',url:'https://api.openai.com/v1/chat/completions',headers:{'Authorization':'Bearer '+OPENAI_KEY,'Content-Type':'application/json'},body:{model:'gpt-4o-mini',temperature:0.4,messages:[{role:'system',content:'You write a solo founders 4-line morning brief. Plain, calm, no hype. Line 1: the money. Line 2: customers. Line 3: one thing worth noticing. Line 4: a single suggested focus for today. No greetings.'},{role:'user',content:facts}]}});summary=String(r.choices[0].message.content||facts).trim();}catch(e){}

const d=now.toLocaleDateString('en-US',{timeZone:TZ,weekday:'long',month:'short',day:'numeric'});
return[{json:{net:net,count:count,newCust:newCust,_subject:'Morning brief - '+d+' - $'+net.toFixed(0)+' yesterday',_body:summary+'\n\n---\n'+facts}}];
